WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_term_index'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '指数', 'kp-xingce-data-term-index', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "指数"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "指数是去掉了百分号的相对值，把比较基准强行设定为 100。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "图表材料最爱用。表头写着“居民消费价格指数（以上年为100）”，里面全是一堆 102.5, 98.6 之类的数字。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "增长率 = (指数 - 100) \\%"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到图表全是100左右的数字] --> B[立刻找表头确认基准]\nB --> C{基准是谁?}\nC -- 以上年为100 --> D[该指数减去100就是今年的同比增速]\nC -- 以特定年(如2015)为100 --> E[该指数减去100是相对2015年的累计增速]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年CPI指数（以上年为100）为 103.5，2022年为 98.2。问2023年CPI相比上年是涨了还是跌了？涨跌幅是多少？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：以上年为100的指数题。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算2023年增速：103.5 - 100 = +3.5%。结论：上涨了 3.5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算2022年增速：98.2 - 100 = -1.8%。结论：2022年是下跌了 1.8%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一秒即答，完全不需要两年的指数去做除法！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "⚠️ 定基指数 vs 环比指数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果表头是“以2010年为100”，你拿 2023 年的指数（150）减去 100 得到的 50%，是2023年相对 2010年 的总增长率，不是2023年相比2022年的增长率！千万看清表头括号里写的是什么！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "以后看到“以上年为100”的指数表，在心里默默给所有大于 100 的数标上正号并加 %，所有小于 100 的标上负号加 %，瞬间把它们还原成增速，题就变成了白给的。"}]}]}$$ AS jsonb), NULL, '指数的核心考点与速算。', category_node.id, CAST('["资料分析", "指数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_term_index", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
